import XCTest
import simd
@testable import MacVisualizerCore

final class HeightfieldVisualizerTests: XCTestCase {

    // Golden snapshots for the default-output regression guards. Each is the
    // flattened [position.x, position.y, color.r, color.g, color.b, color.a] of
    // every emitted vertex (Float little-endian bit patterns, base64), captured
    // from the value-preserving implementation at VisualizerSettings.defaults
    // with a NON-uniform band ramp, aspect 1.5, first frame (dt = 0). A ramp (not
    // a flat field) is used so each column maps to a distinct energy — the
    // snapshot then catches displacement, projection, lighting, color, and
    // ordering regressions, not just count and endpoints.
    private static let wireframeDefaultGolden = ""
    private static let solidDefaultGolden = ""

    private func frame(bands: [Float], L: [Float]? = nil, R: [Float]? = nil, beat: Bool = false, intensity: Float = 0) -> AudioFrame {
        if let L, let R {
            return AudioFrame(bands: bands, bandsLeft: L, bandsRight: R,
                              bandPeaks: bands, waveform: [],
                              rms: 0, peak: 0, timestamp: 0,
                              beat: beat, beatIntensity: intensity)
        }
        return AudioFrame(bands: bands, bandPeaks: bands, waveform: [],
                          rms: 0, peak: 0, timestamp: 0,
                          beat: beat, beatIntensity: intensity)
    }

    private func rampFrame() -> AudioFrame {
        return frame(bands: (0..<48).map { Float($0) / 47.0 })
    }

    /// Bit-exact Float comparison (compares IEEE-754 bit patterns). Catches
    /// ULP-level drift that a tolerance like 1e-6 would silently swallow — the
    /// exact failure mode that let the tiltAngle default regress unnoticed.
    private func assertBitExact(_ a: Float, _ b: Float, _ msg: String) {
        XCTAssertEqual(a.bitPattern, b.bitPattern, msg)
    }

    /// Critical regression guard: at VisualizerSettings.defaults the WIREFRAME
    /// geometry must be byte-identical to the pre-settings hardcoded path.
    func testWireframeDefaultOutputUnchanged() {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        s.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        let out = HeightfieldVisualizer().makeVertices(frame: rampFrame(), settings: s, aspect: 1.5)
        let goldenData = Data(base64Encoded: Self.wireframeDefaultGolden)!
        let golden = goldenData.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        XCTAssertEqual(golden.count, out.count * 6)
        for (i, v) in out.enumerated() {
            let base = i * 6
            assertBitExact(v.position.x, golden[base + 0], "position.x @ vertex \(i)")
            assertBitExact(v.position.y, golden[base + 1], "position.y @ vertex \(i)")
            assertBitExact(v.color.x,    golden[base + 2], "color.r @ vertex \(i)")
            assertBitExact(v.color.y,    golden[base + 3], "color.g @ vertex \(i)")
            assertBitExact(v.color.z,    golden[base + 4], "color.b @ vertex \(i)")
            assertBitExact(v.color.w,    golden[base + 5], "color.a @ vertex \(i)")
        }
    }

    /// Critical regression guard: at VisualizerSettings.defaults the SOLID
    /// geometry must be byte-identical to the pre-settings hardcoded path.
    func testSolidDefaultOutputUnchanged() {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        s.mutateCurrent { $0.heightfieldRenderMode = .solid }
        let out = HeightfieldVisualizer().makeVertices(frame: rampFrame(), settings: s, aspect: 1.5)
        let goldenData = Data(base64Encoded: Self.solidDefaultGolden)!
        let golden = goldenData.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        XCTAssertEqual(golden.count, out.count * 6)
        for (i, v) in out.enumerated() {
            let base = i * 6
            assertBitExact(v.position.x, golden[base + 0], "position.x @ vertex \(i)")
            assertBitExact(v.position.y, golden[base + 1], "position.y @ vertex \(i)")
            assertBitExact(v.color.x,    golden[base + 2], "color.r @ vertex \(i)")
            assertBitExact(v.color.y,    golden[base + 3], "color.g @ vertex \(i)")
            assertBitExact(v.color.z,    golden[base + 4], "color.b @ vertex \(i)")
            assertBitExact(v.color.w,    golden[base + 5], "color.a @ vertex \(i)")
        }
    }

    /// The tiltAngle default must recover the EXACT old `Float.pi / 7.5` bit
    /// pattern (1054242639). Storing `Double.pi / 7.5` drifts by 1 ULP
    /// (1054242640); storing `Double(Float.pi / 7.5)` round-trips losslessly.
    func testTiltAngleDefaultRecoversOldFloatBitPattern() {
        let recovered = Float(VisualizerSettings.defaults.heightfieldTiltAngle)
        XCTAssertEqual(recovered.bitPattern, 1054242639)
        XCTAssertEqual(recovered.bitPattern, (Float.pi / 7.5).bitPattern)
    }

    func testWireframeModeVertexBounds() {
        var s = VisualizerSettings.defaults
        s.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        s.visualizerStyle = .heightfield
        let bands: [Float] = (0..<48).map { _ in 0.7 }
        let viz = HeightfieldVisualizer()
        let verts = viz.makeVertices(frame: frame(bands: bands), settings: s, aspect: 1.6)
        XCTAssertGreaterThan(verts.count, 100)
        for v in verts {
            XCTAssertLessThanOrEqual(abs(v.position.x), 1.5)
            XCTAssertLessThanOrEqual(abs(v.position.y), 1.5)
        }
    }

    func testWireframeBeatBoostExtendsZRange() {
        var s = VisualizerSettings.defaults
        s.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        s.visualizerStyle = .heightfield
        let bands: [Float] = (0..<48).map { _ in 0.7 }
        let baseViz = HeightfieldVisualizer()
        let beatViz = HeightfieldVisualizer()
        let baseVerts = baseViz.makeVertices(frame: frame(bands: bands, beat: false), settings: s, aspect: 1)
        let beatVerts = beatViz.makeVertices(frame: frame(bands: bands, beat: true, intensity: 1.0), settings: s, aspect: 1)
        // Beat should extend the y-range (Z displacement projected to screen).
        let baseSpan = (baseVerts.map(\.position.y).max() ?? 0) - (baseVerts.map(\.position.y).min() ?? 0)
        let beatSpan = (beatVerts.map(\.position.y).max() ?? 0) - (beatVerts.map(\.position.y).min() ?? 0)
        XCTAssertGreaterThan(beatSpan, baseSpan)
    }

    func testWireframeStereoSplitsLeftRight() {
        var s = VisualizerSettings.defaults
        s.useStereoImage = true
        s.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        s.visualizerStyle = .heightfield
        let L: [Float] = [Float](repeating: 0.9, count: 48)
        let R: [Float] = [Float](repeating: 0.0, count: 48)
        let bands = zip(L, R).map { ($0 + $1) / 2 }
        let viz = HeightfieldVisualizer()
        let verts = viz.makeVertices(frame: frame(bands: bands, L: L, R: R), settings: s, aspect: 1)
        // Left half (x < 0) should have larger y spread than right half (x ≥ 0).
        let leftHalf = verts.filter { $0.position.x < 0 }.map(\.position.y)
        let rightHalf = verts.filter { $0.position.x >= 0 }.map(\.position.y)
        let leftSpan = (leftHalf.max() ?? 0) - (leftHalf.min() ?? 0)
        let rightSpan = (rightHalf.max() ?? 0) - (rightHalf.min() ?? 0)
        XCTAssertGreaterThan(leftSpan, rightSpan + 0.05)
    }

    func testSolidModeProducesTriangles() {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        s.mutateCurrent { $0.heightfieldRenderMode = .solid }
        let bands: [Float] = (0..<48).map { _ in 0.7 }
        let viz = HeightfieldVisualizer()
        let verts = viz.makeVertices(frame: frame(bands: bands), settings: s, aspect: 1)
        // 16×16 grid → 15×15 cells × 2 triangles × 3 verts = 1350
        XCTAssertEqual(verts.count, 15 * 15 * 2 * 3)
        XCTAssertEqual(verts.count % 3, 0)
    }

    func testSolidModeProducesDarkerColorsThanWireframe() {
        // The solid path multiplies palette colors by the lighting term (≥ 0.3),
        // so on a flat field the colors are slightly darker than the unshaded
        // wireframe equivalent. Just verify the modes produce different vertex
        // counts (sanity check that the switch is exercised).
        var sWire = VisualizerSettings.defaults
        sWire.visualizerStyle = .heightfield
        sWire.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        var sSolid = VisualizerSettings.defaults
        sSolid.visualizerStyle = .heightfield
        sSolid.mutateCurrent { $0.heightfieldRenderMode = .solid }
        let bands: [Float] = (0..<48).map { _ in 0.5 }
        let viz1 = HeightfieldVisualizer()
        let viz2 = HeightfieldVisualizer()
        let wireVerts = viz1.makeVertices(frame: frame(bands: bands), settings: sWire, aspect: 1)
        let solidVerts = viz2.makeVertices(frame: frame(bands: bands), settings: sSolid, aspect: 1)
        XCTAssertNotEqual(wireVerts.count, solidVerts.count)
    }

    // MARK: - Field reads + clamps

    private func solidSettings(_ configure: (inout VisualizerSettings) -> Void = { _ in }) -> VisualizerSettings {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        s.mutateCurrent { $0.heightfieldRenderMode = .solid }
        configure(&s)
        return s
    }
    private func wireSettings(_ configure: (inout VisualizerSettings) -> Void = { _ in }) -> VisualizerSettings {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        s.mutateCurrent { $0.heightfieldRenderMode = .wireframe }
        configure(&s)
        return s
    }
    private func ySpan(_ v: [BarVertex]) -> Float { (v.map(\.position.y).max() ?? 0) - (v.map(\.position.y).min() ?? 0) }
    private func xSpan(_ v: [BarVertex]) -> Float { (v.map(\.position.x).max() ?? 0) - (v.map(\.position.x).min() ?? 0) }
    private func allFinite(_ v: [BarVertex]) -> Bool {
        v.allSatisfy {
            $0.position.x.isFinite && $0.position.y.isFinite &&
            $0.color.x.isFinite && $0.color.y.isFinite && $0.color.z.isFinite && $0.color.w.isFinite
        }
    }
    private let rampBands: [Float] = (0..<48).map { Float($0) / 47.0 }

    // gridSize -------------------------------------------------------------
    func testGridSizeChangesSolidVertexCount() {
        let n = 32
        let verts = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldGridSize = n }, aspect: 1)
        XCTAssertEqual(verts.count, (n - 1) * (n - 1) * 2 * 3)
    }
    func testGridSizeClampsToMinimumTwo() {
        func count(_ g: Int) -> Int {
            HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldGridSize = g }, aspect: 1).count
        }
        XCTAssertEqual(count(1), count(2), "gridSize 1 clamps to 2")
        XCTAssertEqual(count(0), count(2), "gridSize 0 clamps to 2")
        XCTAssertEqual(count(-9), count(2), "negative gridSize clamps to 2")
        XCTAssertNotEqual(count(2), count(16), "gridSize is actually read")
    }
    func testGridSizeClampsToMaximum64() {
        func count(_ g: Int) -> Int {
            HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldGridSize = g }, aspect: 1).count
        }
        XCTAssertEqual(count(1000), count(64), "gridSize 1000 clamps to 64")
        XCTAssertEqual(count(64), (64 - 1) * (64 - 1) * 2 * 3)
    }

    // tilt / projection ----------------------------------------------------
    func testTiltAngleAffectsOutput() {
        let a = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldTiltAngle = 0 }, aspect: 1)
        let b = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldTiltAngle = 1.2 }, aspect: 1)
        XCTAssertNotEqual(ySpan(a), ySpan(b), accuracy: 0)
    }
    func testVerticalFitAffectsOutput() {
        let a = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldVerticalFit = 0.6 }, aspect: 1)
        let b = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldVerticalFit = 1.15 }, aspect: 1)
        XCTAssertGreaterThan(ySpan(b), ySpan(a))
    }
    func testVerticalCenterShiftsOutput() {
        let a = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldVerticalCenter = -0.4 }, aspect: 1)
        let b = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldVerticalCenter = 0.4 }, aspect: 1)
        let midA = (a.map(\.position.y).max()! + a.map(\.position.y).min()!) / 2
        let midB = (b.map(\.position.y).max()! + b.map(\.position.y).min()!) / 2
        XCTAssertNotEqual(midA, midB, accuracy: 0)
    }

    // extents --------------------------------------------------------------
    func testXExtentScalesGeometry() {
        let base = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings(), aspect: 1)
        let wide = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldXExtent = 2.0 }, aspect: 1)
        XCTAssertEqual(xSpan(wide), xSpan(base) * 2, accuracy: 1e-5)
    }
    func testYExtentScalesGeometry() {
        // Flat field (no Z displacement) so y-span is pure geometry; tilt 0 too.
        let flat = [Float](repeating: 0, count: 48)
        let base = HeightfieldVisualizer().makeVertices(frame: frame(bands: flat), settings: solidSettings { $0.heightfieldTiltAngle = 0 }, aspect: 1)
        let tall = HeightfieldVisualizer().makeVertices(frame: frame(bands: flat), settings: solidSettings { $0.heightfieldTiltAngle = 0; $0.heightfieldYExtent = 2.0 }, aspect: 1)
        XCTAssertEqual(ySpan(tall), ySpan(base) * 2, accuracy: 1e-5)
    }
    func testExtentsClampPositiveAndStayFinite() {
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldXExtent = 0; $0.heightfieldYExtent = -1 }, aspect: 1)
        XCTAssertTrue(allFinite(v))
    }

    // zScale ---------------------------------------------------------------
    func testZScaleScalesHeight() {
        let small = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldZScale = 0.1 }, aspect: 1)
        let big = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldZScale = 0.6 }, aspect: 1)
        XCTAssertGreaterThan(ySpan(big), ySpan(small))
    }
    func testZScaleZeroProducesFiniteColors() {
        // The positive color-denominator floor keeps colors finite at zScale 0.
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldZScale = 0 }, aspect: 1)
        XCTAssertTrue(allFinite(v))
    }

    // wireframe line thickness --------------------------------------------
    func testLineHalfThicknessAffectsWireframeSpread() {
        let thin = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldLineHalfThickness = 0.001 }, aspect: 1)
        let thick = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldLineHalfThickness = 0.02 }, aspect: 1)
        XCTAssertGreaterThan(xSpan(thick), xSpan(thin))
    }
    func testLineHalfThicknessClampNonNegative() {
        let neg = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldLineHalfThickness = -0.05 }, aspect: 1)
        let zero = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldLineHalfThickness = 0 }, aspect: 1)
        XCTAssertTrue(allFinite(neg))
        // Negative clamps to 0 → identical geometry to an explicit 0.
        XCTAssertEqual(xSpan(neg), xSpan(zero), accuracy: 1e-7)
    }

    // solid lighting -------------------------------------------------------
    func testLightDirectionAffectsSolidColors() {
        let a = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldLightX = 0.5; $0.heightfieldLightY = 0.7; $0.heightfieldLightZ = 0.5 }, aspect: 1)
        let b = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldLightX = -0.9; $0.heightfieldLightY = -0.2; $0.heightfieldLightZ = 0.1 }, aspect: 1)
        let sumA = a.reduce(Float(0)) { $0 + $1.color.x + $1.color.y + $1.color.z }
        let sumB = b.reduce(Float(0)) { $0 + $1.color.x + $1.color.y + $1.color.z }
        XCTAssertNotEqual(sumA, sumB, accuracy: 1e-4)
    }
    func testLightDirectionZeroGuardMatchesDefault() {
        // (0,0,0) falls back to the default direction (0.5,0.7,0.5).
        let zero = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldLightX = 0; $0.heightfieldLightY = 0; $0.heightfieldLightZ = 0 }, aspect: 1)
        let def = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings(), aspect: 1)
        XCTAssertTrue(allFinite(zero))
        XCTAssertEqual(zero.count, def.count)
        for (z, d) in zip(zero, def) {
            XCTAssertEqual(z.color.x, d.color.x, accuracy: 1e-6)
            XCTAssertEqual(z.color.y, d.color.y, accuracy: 1e-6)
            XCTAssertEqual(z.color.z, d.color.z, accuracy: 1e-6)
        }
    }
    func testAmbientLightRaisesDarkestColor() {
        let lo = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldAmbientLight = 0.05 }, aspect: 1)
        let hi = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldAmbientLight = 0.9 }, aspect: 1)
        func minLum(_ v: [BarVertex]) -> Float { v.map { $0.color.x + $0.color.y + $0.color.z }.min() ?? 0 }
        XCTAssertGreaterThan(minLum(hi), minLum(lo))
    }
    func testAmbientLightClampStaysFinite() {
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldAmbientLight = 5 }, aspect: 1)
        XCTAssertTrue(allFinite(v))
    }

    // beat -----------------------------------------------------------------
    func testBeatBoostScalesBeatResponse() {
        let flatBands = [Float](repeating: 0.7, count: 48)
        let small = HeightfieldVisualizer().makeVertices(frame: frame(bands: flatBands, beat: true, intensity: 1), settings: solidSettings { $0.heightfieldBeatBoost = 0.1 }, aspect: 1)
        let big = HeightfieldVisualizer().makeVertices(frame: frame(bands: flatBands, beat: true, intensity: 1), settings: solidSettings { $0.heightfieldBeatBoost = 2.5 }, aspect: 1)
        XCTAssertGreaterThan(ySpan(big), ySpan(small))
    }
    func testBeatHalfLifeClampPositiveStaysFinite() {
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands, beat: true, intensity: 1), settings: solidSettings { $0.heightfieldBeatHalfLife = 0 }, aspect: 1)
        XCTAssertTrue(allFinite(v))
    }

    // opacity --------------------------------------------------------------
    func testOpacityFlowsToWireframeAlpha() {
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldOpacity = 0.5 }, aspect: 1)
        XCTAssertTrue(v.allSatisfy { abs($0.color.w - 0.5) < 1e-5 })
    }
    func testOpacityFlowsToSolidAlpha() {
        let v = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: solidSettings { $0.heightfieldOpacity = 0.5 }, aspect: 1)
        XCTAssertTrue(v.allSatisfy { abs($0.color.w - 0.5) < 1e-5 })
    }
    func testOpacityClampsToUnitRange() {
        let over = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldOpacity = 3 }, aspect: 1)
        let under = HeightfieldVisualizer().makeVertices(frame: frame(bands: rampBands), settings: wireSettings { $0.heightfieldOpacity = -2 }, aspect: 1)
        XCTAssertTrue(over.allSatisfy { abs($0.color.w - 1) < 1e-5 })
        XCTAssertTrue(under.allSatisfy { abs($0.color.w - 0) < 1e-5 })
    }

    // MARK: - Read-site clamps for fields whose UI range must not be bypassable
    //         by persisted/edited JSON. Each clamp is INERT at the default
    //         (the default lives strictly inside the range), so value
    //         preservation holds; an out-of-range persisted value collapses
    //         onto the nearest bound.

    /// Bit-exact equality over two emitted vertex arrays.
    private func sameVerts(_ a: [BarVertex], _ b: [BarVertex]) -> Bool {
        guard a.count == b.count else { return false }
        for (x, y) in zip(a, b) {
            if x.position.x.bitPattern != y.position.x.bitPattern { return false }
            if x.position.y.bitPattern != y.position.y.bitPattern { return false }
            if x.color.x.bitPattern != y.color.x.bitPattern { return false }
            if x.color.y.bitPattern != y.color.y.bitPattern { return false }
            if x.color.z.bitPattern != y.color.z.bitPattern { return false }
            if x.color.w.bitPattern != y.color.w.bitPattern { return false }
        }
        return true
    }
    private func solidRender(_ configure: (inout VisualizerSettings) -> Void, beat: Bool = false) -> [BarVertex] {
        let f = beat ? frame(bands: [Float](repeating: 0.7, count: 48), beat: true, intensity: 1) : frame(bands: rampBands)
        return HeightfieldVisualizer().makeVertices(frame: f, settings: solidSettings(configure), aspect: 1)
    }

    func testTiltAngleClampsToRange() {
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldTiltAngle = 99 }, solidRender { $0.heightfieldTiltAngle = 1.5 }), "above 1.5 clamps to 1.5")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldTiltAngle = -5 }, solidRender { $0.heightfieldTiltAngle = 0 }), "below 0 clamps to 0")
        XCTAssertFalse(sameVerts(solidRender { _ in }, solidRender { $0.heightfieldTiltAngle = 1.5 }), "default is in range, not clamped to a bound")
    }

    func testLightDirectionComponentsClampToRange() {
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightX = 99 }, solidRender { $0.heightfieldLightX = 1 }), "lightX above 1 clamps to 1")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightX = -99 }, solidRender { $0.heightfieldLightX = -1 }), "lightX below -1 clamps to -1")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightY = 99 }, solidRender { $0.heightfieldLightY = 1 }), "lightY above 1 clamps to 1")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightY = -99 }, solidRender { $0.heightfieldLightY = -1 }), "lightY below -1 clamps to -1")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightZ = 99 }, solidRender { $0.heightfieldLightZ = 1 }), "lightZ above 1 clamps to 1")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldLightZ = -99 }, solidRender { $0.heightfieldLightZ = -1 }), "lightZ below -1 clamps to -1")
        XCTAssertFalse(sameVerts(solidRender { _ in }, solidRender { $0.heightfieldLightX = 1 }), "default lightX (0.5) is in range, not clamped")
    }

    func testVerticalFitClampsToRange() {
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldVerticalFit = 99 }, solidRender { $0.heightfieldVerticalFit = 1.2 }), "above 1.2 clamps to 1.2")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldVerticalFit = -99 }, solidRender { $0.heightfieldVerticalFit = 0.5 }), "below 0.5 clamps to 0.5")
        XCTAssertFalse(sameVerts(solidRender { _ in }, solidRender { $0.heightfieldVerticalFit = 1.2 }), "default 0.92 is in range, not clamped")
    }

    func testVerticalCenterClampsToRange() {
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldVerticalCenter = 99 }, solidRender { $0.heightfieldVerticalCenter = 0.5 }), "above 0.5 clamps to 0.5")
        XCTAssertTrue(sameVerts(solidRender { $0.heightfieldVerticalCenter = -99 }, solidRender { $0.heightfieldVerticalCenter = -0.5 }), "below -0.5 clamps to -0.5")
        XCTAssertFalse(sameVerts(solidRender { _ in }, solidRender { $0.heightfieldVerticalCenter = 0.5 }), "default 0.071 is in range, not clamped")
    }

    func testBeatBoostClampsToRange() {
        XCTAssertTrue(sameVerts(solidRender({ $0.heightfieldBeatBoost = 99 }, beat: true), solidRender({ $0.heightfieldBeatBoost = 3 }, beat: true)), "above 3 clamps to 3")
        XCTAssertTrue(sameVerts(solidRender({ $0.heightfieldBeatBoost = -99 }, beat: true), solidRender({ $0.heightfieldBeatBoost = 0 }, beat: true)), "below 0 clamps to 0")
        XCTAssertFalse(sameVerts(solidRender({ _ in }, beat: true), solidRender({ $0.heightfieldBeatBoost = 3 }, beat: true)), "default 0.4 is in range, not clamped")
    }

    // MARK: - Auto-placement toggles (fill width / anchor bottom)

    private func hfFrame(_ level: Float, count: Int = 32) -> AudioFrame {
        let bands = [Float](repeating: level, count: count)
        return AudioFrame(bands: bands, bandPeaks: bands, waveform: [0, 0],
                          rms: level, peak: level, timestamp: 0)
    }

    private func hfSettings(_ mutate: (inout VisualizerSettings) -> Void = { _ in }) -> VisualizerSettings {
        var s = VisualizerSettings.defaults
        s.visualizerStyle = .heightfield
        mutate(&s)
        return s
    }

    /// Fill width makes the grid span the full NDC width at any aspect, in both
    /// render modes (they share the projection).
    func testHeightfieldFillWidthSpansFullWidth() {
        for mode in [HeightfieldRenderMode.wireframe, .solid] {
            for aspect in [Float(0.6), Float(1.0), Float(2.2)] {
                let s = hfSettings {
                    $0.heightfieldFillWidth = true
                    $0.mutateCurrent { p in p.heightfieldRenderMode = mode }
                }
                let verts = HeightfieldVisualizer().makeVertices(frame: hfFrame(0.5), settings: s, aspect: aspect)
                let maxAbsX = verts.map { abs($0.position.x) }.max()!
                XCTAssertGreaterThan(maxAbsX, 0.98, "\(mode) aspect \(aspect): did not reach the side edges")
                XCTAssertLessThan(maxAbsX, 1.08, "\(mode) aspect \(aspect): overshot the width")
            }
        }
    }

    /// Anchor bottom pins the resting grid's lowest row to the bottom edge.
    func testHeightfieldAnchorBottomPinsToBottomEdge() {
        for aspect in [Float(0.6), Float(1.0), Float(2.2)] {
            let s = hfSettings { $0.heightfieldAnchorBottom = true }
            let verts = HeightfieldVisualizer().makeVertices(frame: hfFrame(0), settings: s, aspect: aspect)
            let minY = verts.map { $0.position.y }.min()!
            XCTAssertLessThan(minY, -0.98, "aspect \(aspect): not pinned to the bottom")
            XCTAssertGreaterThan(minY, -1.08, "aspect \(aspect): pushed past the bottom")
        }
    }

    /// The two toggles are orthogonal: the projection's x depends only on
    /// xExtent and y only on the vertical terms, so each leaves the other axis
    /// bit-identical.
    func testHeightfieldTogglesAreIndependentPerAxis() {
        let f = hfFrame(0.6)
        let base = HeightfieldVisualizer().makeVertices(frame: f, settings: hfSettings(), aspect: 1.7)
        let wide = HeightfieldVisualizer().makeVertices(
            frame: f, settings: hfSettings { $0.heightfieldFillWidth = true }, aspect: 1.7)
        let low = HeightfieldVisualizer().makeVertices(
            frame: f, settings: hfSettings { $0.heightfieldAnchorBottom = true }, aspect: 1.7)
        XCTAssertEqual(base.count, wide.count)
        XCTAssertEqual(base.count, low.count)
        for (b, w) in zip(base, wide) {
            XCTAssertEqual(w.position.y, b.position.y, accuracy: 1e-6, "fill width moved y")
        }
        for (b, l) in zip(base, low) {
            XCTAssertEqual(l.position.x, b.position.x, accuracy: 1e-6, "anchor bottom moved x")
        }
    }

    func testHeightfieldTogglesOffAreUnchanged() {
        let f = hfFrame(0.5)
        var off = hfSettings()
        off.heightfieldFillWidth = false
        off.heightfieldAnchorBottom = false
        XCTAssertEqual(HeightfieldVisualizer().makeVertices(frame: f, settings: off, aspect: 1.5),
                       HeightfieldVisualizer().makeVertices(frame: f, settings: hfSettings(), aspect: 1.5))
    }
}
